//! Decode the AutoEQ corpus off the UI thread.
//!
//! The asset is embedded in the binary (1.6 MB), so there is no filesystem
//! access, but decoding 8,850 entries allocates thousands of strings and
//! band vectors. That work must not happen inside a frame. The service starts
//! once, when the AutoEQ dialog first opens, and the shell polls it until it
//! reports a catalog or an error.

use std::sync::Arc;

use crossbeam::channel::{unbounded, Receiver, TryRecvError};

use crate::state::AutoEqCatalog;

/// Generated by `scripts/generate-autoeq-corpus.py`; see
/// `assets/autoeq/ATTRIBUTION.md`.
const CORPUS: &[u8] = include_bytes!("../../assets/autoeq/autoeq_parametric.bin");

#[derive(Default)]
pub struct AutoEqCatalogService {
    rx: Option<Receiver<Result<Arc<AutoEqCatalog>, String>>>,
    finished: bool,
}

impl AutoEqCatalogService {
    pub fn new() -> Self {
        Self::default()
    }

    /// Start the decode once. Repeated calls are cheap and do not restart it.
    pub fn ensure_started(&mut self) -> Result<(), String> {
        if self.rx.is_some() || self.finished {
            return Ok(());
        }
        let (tx, rx) = unbounded();
        let spawned = std::thread::Builder::new()
            .name("shadow-autoeq-catalog".into())
            .spawn(move || {
                let _ = tx.send(AutoEqCatalog::decode(CORPUS).map(Arc::new));
            });
        match spawned {
            Ok(_) => {
                self.rx = Some(rx);
                Ok(())
            }
            Err(e) => {
                self.finished = true;
                Err(format!("could not start the AutoEQ catalog worker: {e}"))
            }
        }
    }

    /// Return the result once, then go idle.
    pub fn poll(&mut self) -> Option<Result<Arc<AutoEqCatalog>, String>> {
        let rx = self.rx.as_ref()?;
        match rx.try_recv() {
            Ok(result) => {
                self.rx = None;
                self.finished = true;
                Some(result)
            }
            Err(TryRecvError::Empty) => None,
            Err(TryRecvError::Disconnected) => {
                self.rx = None;
                self.finished = true;
                Some(Err(
                    "the AutoEQ catalog worker stopped unexpectedly".to_string()
                ))
            }
        }
    }

    pub fn is_loading(&self) -> bool {
        self.rx.is_some()
    }
}
